/* Contenido de «Ciberseguridad Personal y Prevención de Fraudes». Archivo generado con herramientas/dividir-catalogo.js: no se edita a mano. */
window.MARA_CONTENIDO("c-ciberseguridad",{"l":{"c-ciberseguridad-m1-l1":[{"tipo":"destacado","texto":"<b>Sobre este curso:</b> es un curso libre de capacitación con constancia de Instituto Mara; no tiene validez oficial ante la SEP ni es una certificación del CONOCER. Su enfoque es 100% preventivo: aprenderás a protegerte, no a atacar. No sustituye la asesoría de tu banco, de un abogado ni la atención de las autoridades cuando ya ocurrió un delito."},{"tipo":"texto","texto":"La mayoría de los fraudes que le pasan a la gente común no requieren «hackear» nada. El estafador no rompe la seguridad de tu banco: <b>te convence a ti</b> de que le des la llave. A eso se le llama <b>ingeniería social</b>: manipular a una persona para que entregue datos, códigos o dinero por su propia mano.<br><br>Por eso la mejor defensa no es una app mágica, sino reconocer el truco a tiempo. Y el truco casi siempre es el mismo: provocar una emoción fuerte para que actúes <b>antes</b> de pensar."},{"tipo":"tabla","titulo":"Las cuatro palancas del estafador","encabezados":["Palanca","Cómo suena","Qué busca"],"filas":[["<b>Urgencia</b>","«Tienes 10 minutos», «tu cuenta se bloquea hoy», «última oportunidad»","Que no tengas tiempo de verificar ni de preguntarle a nadie"],["<b>Autoridad</b>","«Le hablo del área de seguridad de su banco», «soy del SAT», «habla el licenciado de la fiscalía»","Que obedezcas sin cuestionar porque «es oficial»"],["<b>Miedo</b>","«Detectamos un cargo de $18,500», «tenemos a tu hijo», «vas a ir a Buró»","Que el susto te nuble el juicio"],["<b>Premio</b>","«Ganaste una pantalla», «préstamo aprobado sin Buró», «gana $3,000 diarios desde casa»","Que la ilusión te haga bajar la guardia"]],"nota":"Muchas estafas combinan dos o tres palancas a la vez: «(autoridad) soy de tu banco, (miedo) hay un cargo sospechoso y (urgencia) hay que cancelarlo ya»."},{"tipo":"tarjetas","rotulo":"Voltea la tarjeta: ¿qué palanca usan?","tarjetas":[{"frente":"«Estimado cliente, su tarjeta será cancelada en 24 horas. Actualice sus datos aquí.»","reverso":"<b>Urgencia y miedo.</b> Ningún banco cancela tu tarjeta por no dar clic a un enlace."},{"frente":"«Felicidades, fuiste elegido para recibir una despensa del gobierno. Solo paga el envío.»","reverso":"<b>Premio.</b> Si para recibir algo «gratis» tienes que pagar, es fraude."},{"frente":"«Habla el agente Ramírez de la Policía Cibernética. Su número está ligado a un delito.»","reverso":"<b>Autoridad y miedo.</b> La policía no te cita ni te «arregla» nada por teléfono a cambio de dinero."},{"frente":"«Mamá, cambié de número. Necesito que me deposites urgente, luego te explico.»","reverso":"<b>Urgencia y confianza.</b> Llama al número de siempre antes de mover un peso."}]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"La ingeniería social consiste en…","ops":["Instalar antenas falsas de telefonía","Manipular a la persona para que entregue datos, códigos o dinero","Descifrar contraseñas con computadoras potentes"],"correcta":1,"explica":"El eslabón que atacan eres tú, no el sistema del banco."},{"p":"«Tienes 10 minutos para confirmar o pierdes tu saldo» es sobre todo una palanca de…","ops":["Urgencia","Premio","Autoridad"],"correcta":0,"explica":"Las prisas son la señal número uno de alerta."},{"p":"Ante un mensaje que te provoca miedo o prisa, lo más seguro es…","ops":["Responder rápido para no perder la oportunidad","Reenviarlo a tus contactos para que opinen","Hacer una pausa y verificar por un canal que tú elijas"],"correcta":2,"explica":"La emoción fuerte es justo lo que busca el estafador."}]},{"tipo":"reflexion","rotulo":"Tu punto débil","pregunta":"¿Qué palanca crees que funcionaría mejor contigo: la urgencia, la autoridad, el miedo o el premio? ¿Por qué?","ayuda":"A mí me haría caer más… porque… Para protegerme voy a…"},{"tipo":"clave","items":["La ingeniería social te convence de entregar tú mismo la llave: datos, códigos o dinero.","Cuatro palancas: urgencia, autoridad, miedo y premio; muchas veces combinadas.","Si un mensaje te acelera el corazón, detente: esa es la señal para verificar."]}],"c-ciberseguridad-m1-l2":[{"tipo":"texto","texto":"Los fraudes cambian de disfraz, pero repiten patrones. Conocer los más comunes te permite reconocerlos aunque lleguen con otro nombre, otro logotipo u otra historia."},{"tipo":"tabla","titulo":"Catálogo de fraudes frecuentes","encabezados":["Fraude","Cómo funciona","La señal clave"],"filas":[["<b>Llamada del «banco»</b>","Te llaman «del área de seguridad» por un cargo sospechoso y te piden el NIP, la clave dinámica, el código que te llegó por SMS o que «transfieras a una cuenta segura».","El banco <b>nunca</b> te pide NIP, contraseñas ni códigos, ni que muevas tu dinero a otra cuenta."],["<b>SMS falso (smishing)</b>","Mensaje de texto de «tu banco», «paquetería» o «multa» con un enlace a una página idéntica a la real.","Enlaces acortados o con dominios raros; te piden datos de tarjeta o de acceso."],["<b>Correo falso (phishing)</b>","Correo que imita al SAT, a tu banco o a una tienda, con un archivo o un enlace.","Remitente extraño, errores, urgencia y adjuntos inesperados."],["<b>WhatsApp secuestrado</b>","Te piden «el código de 6 dígitos que te llegó por error». Con él activan tu WhatsApp en su teléfono y piden dinero a tus contactos.","Ese código es la llave de tu cuenta: <b>jamás</b> se comparte."],["<b>Falso familiar o extorsión telefónica</b>","«Mamá, cambié de número» o «tenemos a tu hijo». Buscan que deposites sin comprobar.","Presión para no colgar y no llamar a nadie."],["<b>Ofertas falsas en Marketplace o redes</b>","Celulares, autos o rentas muy baratos; piden anticipo o «apartado» por transferencia.","Precio demasiado bueno y prisa por que pagues antes de ver el producto."],["<b>Préstamos fraudulentos por app</b>","Apps que prestan «sin Buró», piden acceso a tus contactos y fotos, y luego cobran con amenazas o exhibición.","Piden pago por adelantado o permisos a tus contactos y galería."],["<b>Falso empleo</b>","«Gana dinero dando likes» o trabajos con sueldo alto; primero pagas un curso, un uniforme o «inviertes» para desbloquear ganancias.","Un empleo real no te cobra por contratarte."],["<b>Cargos no reconocidos</b>","Compras que no hiciste por tarjeta clonada o datos robados en una página falsa.","Movimientos pequeños de «prueba» antes de uno grande."]]},{"tipo":"comparar","titulo":"La misma llamada, dos versiones","malTitulo":"Llamada de fraude","mal":"«Buenas tardes, le llamo del área de seguridad de su banco. Detectamos un cargo de $12,800 en una tienda de Monterrey. Para cancelarlo le voy a enviar un código; dígamelo para confirmar que es usted. Es urgente, el cargo se aplica en 5 minutos.»","bienTitulo":"Contacto legítimo","bien":"«Detectamos una compra inusual de $12,800. Si no la reconoces, responde NO o llama al número que viene al reverso de tu tarjeta.» El banco no te pide códigos, no te apura con minutos y te deja llamar tú al número oficial."},{"tipo":"relacionar","rotulo":"Relaciona cada situación con el fraude","pares":[["«Te llegó un código por error, ¿me lo pasas?»","WhatsApp secuestrado"],["SMS: «Tu paquete está retenido, paga $35 aquí»","Smishing"],["«Préstamo aprobado, solo paga la comisión de apertura antes»","Préstamo fraudulento"],["«Gana $2,000 diarios dando like; primero deposita para activar»","Falso empleo"],["iPhone nuevo a mitad de precio con apartado por transferencia","Oferta falsa"]]},{"tipo":"practica","rotulo":"Casos rápidos","preguntas":[{"p":"Doña Carmen recibe una llamada «del banco» que le pide la clave que le acaba de llegar por SMS para «cancelar un cargo». Debe…","ops":["Pedir que le repitan su nombre completo y luego dar la clave","Colgar y llamar ella al número del reverso de su tarjeta","Dar la clave porque la llamada viene del banco"],"correcta":1,"explica":"Aunque sepan tu nombre o los últimos dígitos de tu tarjeta, pueden ser estafadores: esos datos se filtran."},{"p":"Luis encuentra una renta muy barata en Marketplace; el «dueño» está fuera de la ciudad y pide un depósito para apartar sin mostrar el departamento. Es…","ops":["Una señal clásica de fraude","Una práctica normal de renta","Seguro si el anuncio tiene fotos bonitas"],"correcta":0,"explica":"No pagues nada sin ver el inmueble y comprobar quién es el dueño."},{"p":"Una app de préstamos pide acceso a tus contactos y galería para aprobarte. Lo prudente es…","ops":["Aceptar, porque así se aprueba más rápido","Darle los permisos y borrarla después","No darle permisos y verificar que la empresa esté registrada ante CONDUSEF"],"correcta":2,"explica":"Los montadeudas usan tus contactos y fotos para presionarte."}]},{"tipo":"clave","items":["Los fraudes cambian de disfraz, pero repiten patrones: llamada del banco, SMS, correo, WhatsApp, falso familiar, ofertas, préstamos y empleos.","El banco nunca te pide NIP, contraseñas ni códigos, ni que muevas tu dinero a una «cuenta segura».","Precio demasiado bueno, prisa por pagar y cobro por adelantado: tres señales de alarma."]}],"c-ciberseguridad-m1-l3":[{"tipo":"texto","texto":"No necesitas ser experto en tecnología para no caer. Necesitas un hábito: <b>antes de hacer clic, pagar o dictar un código, haz una pausa</b>. Estos cuatro pasos te sirven para llamadas, SMS, WhatsApp, correo y redes sociales."},{"tipo":"pasos","rotulo":"Método «Detente, verifica, no compartas, reporta»","pasos":["<b>Detente:</b> si sientes prisa, miedo o emoción por un premio, no respondas todavía. Cuelga o deja el mensaje en visto.","<b>Verifica por otro canal que tú elijas:</b> llama al número del reverso de tu tarjeta, entra a la app oficial escribiendo tú la dirección o marca al número de siempre de tu familiar.","<b>No compartas:</b> NIP, contraseñas, códigos de SMS, clave dinámica o token, ni fotos de tu tarjeta o INE.","<b>Reporta y bloquea:</b> avisa a tu banco o a la plataforma, bloquea el número y, si ya hubo daño, sigue los pasos del módulo 4."]},{"tipo":"comparar","titulo":"Dos SMS «del banco»","malTitulo":"Probable fraude","mal":"BANC0 AVISO: Su cuenta fue BLOQUEADA por actividad inusual. Reactívela en 30 min aquí: bit.ly/xx-banc0-mx","bienTitulo":"Aviso con características de legítimo","bien":"Tu banco: compra por $1,249 en Tienda X con tarjeta terminación 4821. Si no la reconoces, llama al número al reverso de tu tarjeta. Nunca te pediremos claves ni códigos."},{"tipo":"destacado","texto":"<b>Ojo:</b> aunque un mensaje se vea legítimo, la regla de oro no cambia. No uses el enlace ni el teléfono que viene en el mensaje: <b>verifica tú por el canal oficial</b>. Los estafadores pueden hacer que un SMS aparezca en la misma conversación que los mensajes reales de tu banco."},{"tipo":"practica","rotulo":"¿Es fraude o no?","preguntas":[{"p":"Te escriben por WhatsApp desde un número desconocido con la foto de tu sobrino: «Tío, este es mi nuevo número, ¿me prestas $3,500? Te pago el viernes».","ops":["Es legítimo si escribe como él","Probable fraude: llama al número anterior de tu sobrino antes de depositar","Es legítimo porque tiene su foto"],"correcta":1,"explica":"La foto se copia de redes sociales en segundos."},{"p":"Tu app bancaria, que abriste tú mismo, te muestra una notificación de compra que sí hiciste.","ops":["Es legítimo","Es fraude seguro","Debes borrar la app"],"correcta":0,"explica":"Entrar tú a la app oficial es verificar por tu propio canal."},{"p":"Un correo «del SAT» dice que tienes una multa y trae un archivo comprimido para «ver el detalle».","ops":["Legítimo, porque tiene el logotipo del SAT","Abrirlo en la computadora del trabajo para no dañar la tuya","Probable fraude: no abras el adjunto y revisa tu situación entrando tú al portal oficial"],"correcta":2,"explica":"Los archivos inesperados pueden instalar programas espía."},{"p":"Te llaman para ofrecerte trabajo desde casa: «Solo paga $450 del kit de bienvenida y empiezas hoy».","ops":["Legítimo si te mandan contrato por PDF","Fraude: un empleo real no te cobra por contratarte","Legítimo si el sueldo es bueno"],"correcta":1}]},{"tipo":"completar","rotulo":"Completa la regla","items":[{"frase":"Si un mensaje me provoca prisa o miedo, primero me ___.","resp":["detengo","freno","calmo"]},{"frase":"Verifico por un canal que yo ___, no por el enlace del mensaje.","resp":["elijo","elija","escojo","escoja"]},{"frase":"Nunca comparto el ___ que me llega por SMS.","resp":["código","codigo"]}]},{"tipo":"clave","items":["Detente, verifica por un canal que tú elijas, no compartas y reporta.","Nunca uses el enlace ni el teléfono que trae un mensaje sospechoso.","Fotos, logotipos y nombres se copian fácil: no prueban que alguien sea quien dice ser."]}],"c-ciberseguridad-m1-pr":[{"tipo":"destacado","texto":"<b>El caso.</b> Maribel tiene una tienda de regalos y envolturas en Puebla. Vende por WhatsApp y envía pedidos por paquetería, así que recibe muchos avisos de envíos y pagos. En una sola semana le llega esto:<br><br>• <b>Lunes:</b> un SMS: «Su paquete no pudo ser entregado por dirección incompleta. Pague $28 de reenvío aquí: paqueteria-mx-envios.com».<br>• <b>Miércoles:</b> una llamada «del departamento de fraudes de su banco»: el asesor ya sabe su nombre y los últimos cuatro dígitos de su tarjeta.<br>• <b>Jueves:</b> un WhatsApp de su proveedora de listones, desde su número de siempre: «Amiga, te llegó un código de 6 números por error, ¿me lo reenvías?».<br>• <b>Viernes:</b> un correo que dice venir de una plataforma de ventas: «Tu cuenta será suspendida en 24 horas; confirma tus datos de cobro».<br><br>Tu reto: ayúdala a decidir, mensaje por mensaje, qué hacer. Calcula de 30 a 40 minutos."},{"tipo":"texto","texto":"Antes de responder, recuerda la idea central del módulo: el estafador rara vez rompe un sistema; <b>te empuja a actuar rápido</b>. Por eso, más que memorizar cada tipo de fraude, conviene reconocer las <b>señales</b> que se repiten: prisa, un enlace o un teléfono que viene dentro del mismo mensaje, un cobro pequeño que parece inofensivo, alguien que pide un código, o un conocido que de pronto pide algo raro.<br><br>Un detalle importante del miércoles: que el asesor sepa tu nombre y los últimos cuatro dígitos de tu tarjeta <b>no prueba nada</b>. Esos datos aparecen en tickets, en bases de datos filtradas o en compras que hiciste en otros sitios. Lo que confirma que una llamada es real no es lo que el otro sabe de ti, sino que <b>tú llames</b> al número oficial."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"Lunes. Maribel sí está esperando un paquete. ¿Qué le conviene hacer con el SMS del reenvío de $28?","ops":["Pagar los $28 porque es poco dinero y sí espera un paquete","No abrir el enlace y rastrear el envío con su número de guía en el sitio oficial de la paquetería, escrito por ella misma","Contestar el SMS para pedir más información"],"correcta":1,"explica":"El monto pequeño es la carnada: lo que buscan son los datos de tu tarjeta. Esperar un paquete de verdad hace que el engaño funcione mejor, por eso se verifica con la guía y por el canal que tú eliges."},{"p":"Miércoles. El «asesor» sabe su nombre y los últimos cuatro dígitos de la tarjeta, y le pide confirmar el código que le va a llegar. Lo más seguro es…","ops":["Colgar y marcar ella misma al número que viene al reverso de su tarjeta","Dar el código, porque ya demostró que es del banco","Pedirle al asesor su nombre completo y número de empleado antes de dar el código"],"correcta":0,"explica":"Pedir un nombre o un número de empleado no sirve: el estafador puede inventarlos. Ningún banco te pide por teléfono el código que te envió."},{"p":"Jueves. El mensaje llega del número de siempre de su proveedora. ¿Qué es lo más probable?","ops":["Que la proveedora de verdad se equivocó al escribir su número","Que sea un error de WhatsApp","Que alguien ya robó el WhatsApp de la proveedora y ahora quiere el de Maribel"],"correcta":2,"explica":"Así se roban cuentas en cadena. Lo correcto es no enviar el código y llamarle por teléfono a la proveedora para avisarle."},{"p":"Viernes. ¿Qué detalle del correo es la señal más clara de riesgo?","ops":["Que venga en español","El plazo de 24 horas y la petición de confirmar datos de cobro desde el mismo correo","Que mencione una plataforma que ella sí usa"],"correcta":1,"explica":"Urgencia más enlace para capturar datos es la fórmula típica. Si tienes duda, entra a la plataforma escribiendo tú la dirección o desde su app, nunca desde el correo."}]},{"tipo":"relacionar","rotulo":"Relaciona la señal con el riesgo","pares":[["Un cobro pequeño de reenvío con enlace en SMS","Robo de datos de tu tarjeta en una página falsa"],["Alguien pide el código de 6 dígitos que te llegó","Robo de tu cuenta de WhatsApp"],["El «banco» te pide transferir a una cuenta segura","Te hacen mover tu propio dinero al estafador"],["Un «asesor» te pide instalar una app para ver tu pantalla","Control de tu celular y de tu banca móvil"],["Un conocido pide dinero desde un número nuevo","Suplantación de un familiar o amigo"],["Un correo trae un archivo comprimido para «ver tu multa»","Programa malicioso en tu equipo"]]},{"tipo":"comparar","titulo":"Cómo responde Maribel el jueves","mal":"«Ay, claro, amiga, aquí va: 482 913.» Diez minutos después, sus clientas reciben mensajes pidiendo depósitos para «un pedido urgente».","bien":"No envía el código. Le llama por teléfono a su proveedora: «Oye, me llegó un mensaje raro desde tu WhatsApp pidiéndome un código; creo que te lo robaron». Luego revisa que su propio PIN de verificación en dos pasos esté activo."},{"tipo":"completar","rotulo":"Completa","items":[{"frase":"Para rastrear un paquete uso mi número de ___ en el sitio oficial de la paquetería.","resp":["guía","guia"]},{"frase":"Si alguien dice ser del banco, cuelgo y marco al número que viene al ___ de mi tarjeta.","resp":["reverso","dorso"]},{"frase":"Un código que me llegó a mí nunca se ___ con nadie.","resp":["comparte","reenvía","reenvia","da"]}]},{"tipo":"reflexion","rotulo":"Tu propia semana","pregunta":"Revisa los SMS, correos y mensajes que recibiste en los últimos siete días. Elige dos que te parezcan sospechosos (o, si no hay, dos que recuerdes de antes) y escribe para cada uno: qué señal tenía y qué hiciste o harías ahora.","ayuda":"Mensaje 1: SMS de… La señal fue… Lo correcto es…"},{"tipo":"plantilla","rotulo":"Aviso para tus clientes y contactos","texto":"Aviso importante de [nombre de tu negocio]:\nNunca te pediremos códigos de verificación ni contraseñas.\nNuestros únicos datos para pago son los que te damos en persona o en [canal oficial].\nSi recibes un mensaje a nuestro nombre pidiendo depósitos urgentes o a otra cuenta, no pagues y llámanos al [teléfono fijo o alterno].\nGracias por cuidarte y cuidarnos.","nota":"Cópiala y adáptala. Publícala como mensaje fijado o en tu estado de WhatsApp."},{"tipo":"clave","items":["Un cobro pequeño o un dato tuyo que el otro ya conoce no prueban que el mensaje sea legítimo.","Verifica siempre por el canal que tú eliges: la guía en el sitio oficial, el número al reverso de la tarjeta, la app que tú abres.","Si un conocido te pide un código o dinero de forma rara, llámale antes de hacer nada."]}],"c-ciberseguridad-m2-l1":[{"tipo":"texto","texto":"Tu correo electrónico es la llave maestra: desde ahí se recuperan casi todas tus demás cuentas. Si un estafador entra a tu correo, puede cambiar la contraseña de tus redes, de tus compras en línea y a veces de tus apps financieras.<br><br>El error más común no es tener una contraseña «fácil», sino <b>usar la misma en todas partes</b>. Cuando una tienda o una app sufre una filtración, los delincuentes prueban ese mismo correo y contraseña en otros sitios. Si la repites, cae todo como fichas de dominó."},{"tipo":"comparar","titulo":"Contraseñas débiles contra contraseñas fuertes","malTitulo":"Débil","mal":"<b>Juan1985</b> (tu nombre y año de nacimiento)<br><b>12345678</b> o <b>contraseña</b><br><b>Tigres2024!</b> usada en el correo, Facebook y la tienda en línea","bienTitulo":"Fuerte","bien":"<b>MiPerroComeTacosDeCanastaLosLunes</b> (frase larga, solo tuya)<br>Una contraseña <b>distinta</b> para cada cuenta importante<br>Las demás, generadas y guardadas por un gestor de contraseñas"},{"tipo":"tabla","titulo":"Qué hace fuerte a una contraseña","encabezados":["Característica","Por qué importa"],"filas":[["<b>Larga</b> (idealmente 14 caracteres o más)","Cada carácter extra multiplica el tiempo que tarda un programa en adivinarla. La longitud pesa más que los símbolos raros."],["<b>Única</b>","Si se filtra en un sitio, no abre tus otras cuentas."],["<b>Sin datos personales</b>","Nombres, fechas, equipo favorito o mascota se encuentran en tus redes sociales."],["<b>Guardada en un lugar seguro</b>","Un gestor de contraseñas es mejor que la libreta en la cartera o una nota sin protección en el celular."]]},{"tipo":"pasos","rotulo":"Cómo empezar con un gestor de contraseñas","pasos":["Elige un gestor conocido: el que ya trae tu celular o navegador (por ejemplo, el de Google o el de Apple) o una app reconocida de gestión de contraseñas.","Protégelo con una <b>contraseña maestra</b> larga que solo tú sepas y activa la verificación en dos pasos.","Empieza por lo más importante: <b>correo, banca, WhatsApp y redes sociales</b>.","Cambia las contraseñas repetidas por nuevas, generadas por el gestor.","Deja que el gestor las rellene por ti: además, no escribe tu contraseña en una página falsa porque reconoce que la dirección no coincide."]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"¿Cuál contraseña es más segura?","ops":["LaAbuelaHaceMoleLosDomingos","Maria1990","P@ss1"],"correcta":0,"explica":"La longitud es lo que más protege; una frase larga es fácil de recordar y difícil de adivinar."},{"p":"El mayor riesgo de usar la misma contraseña en todo es que…","ops":["Se te olvida más rápido","El banco la bloquea","Si se filtra en un sitio, abren tus demás cuentas"],"correcta":2,"explica":"Las filtraciones de tiendas y apps son frecuentes."},{"p":"La cuenta que más conviene proteger primero es…","ops":["Tu cuenta de música","Tu correo electrónico, porque desde ahí se recuperan las demás","Tu cuenta de videojuegos"],"correcta":1}]},{"tipo":"ordenar","rotulo":"Ordena la regla de oro","items":[{"frase":"Una contraseña larga y distinta para cada cuenta","es":"Longitud y unicidad"}]},{"tipo":"clave","items":["Tu correo es la llave maestra: protégelo primero.","Contraseñas largas (frases) y distintas para cada cuenta importante.","Un gestor de contraseñas las crea, las guarda y te ayuda a no escribirlas en páginas falsas."]}],"c-ciberseguridad-m2-l2":[{"tipo":"texto","texto":"La <b>verificación en dos pasos</b> (también llamada autenticación de dos factores o 2FA) pide algo más que tu contraseña: un código, una confirmación en tu celular o tu huella. Así, aunque alguien robe tu contraseña, no puede entrar sin ese segundo paso.<br><br>Pero ojo: ese segundo paso solo sirve si <b>nunca se lo das a nadie</b>. Casi todos los robos de WhatsApp en México empiezan con alguien que pide «el código que te llegó por error»."},{"tipo":"tabla","titulo":"Tipos de segundo paso","encabezados":["Método","Cómo funciona","Comentario"],"filas":[["Código por SMS","Te llega un número por mensaje de texto","Mejor que nada; es el más expuesto al engaño."],["App autenticadora","Una app genera códigos que cambian cada 30 segundos","Más segura que el SMS."],["Llave de acceso (passkey) o huella","Confirmas con tu huella, rostro o el bloqueo de tu celular","Muy resistente al robo por páginas falsas."],["PIN de WhatsApp","Un NIP de 6 dígitos que tú eliges y que WhatsApp pide al registrar tu número en otro teléfono","Actívalo: es tu segunda cerradura en WhatsApp."]]},{"tipo":"pasos","rotulo":"Activa la verificación en dos pasos en WhatsApp","pasos":["Abre WhatsApp y entra a <b>Ajustes</b> (o Configuración).","Toca <b>Cuenta</b> y luego <b>Verificación en dos pasos</b> (los nombres de los menús pueden cambiar; así aparecen al momento de escribir).","Toca <b>Activar</b> y escribe un PIN de 6 dígitos que no sea tu fecha de nacimiento ni 123456.","Agrega un correo electrónico de recuperación por si olvidas el PIN.","Repite la idea en tu correo, Facebook, Instagram y TikTok: busca «Seguridad» y activa la verificación en dos pasos."]},{"tipo":"tarjetas","rotulo":"Mitos y realidades","tarjetas":[{"frente":"«Si ya tengo contraseña fuerte, no necesito dos pasos.»","reverso":"<b>Falso.</b> Las contraseñas se filtran o se roban con páginas falsas; el segundo paso las detiene."},{"frente":"«El código me llegó a mí, así que puedo dárselo a quien lo pidió.»","reverso":"<b>Falso.</b> Si te llegó a ti, es para ti. Quien te lo pide está intentando entrar a tu cuenta."},{"frente":"«WhatsApp o mi banco me pueden pedir el código por chat.»","reverso":"<b>Falso.</b> Ninguna empresa seria te pide por chat o por teléfono el código que te envió."},{"frente":"«Activar dos pasos es complicado.»","reverso":"<b>Falso.</b> Toma unos minutos por cuenta y te protege por años."}]},{"tipo":"practica","rotulo":"Casos","preguntas":[{"p":"Tu comadre te escribe: «Te mandé un código por error a tu celular, ¿me lo pasas?». Lo correcto es…","ops":["No pasarlo y llamarle por teléfono: su WhatsApp probablemente ya fue robado","Pasárselo porque es tu comadre","Pasárselo solo si te explica para qué es"],"correcta":0,"explica":"Así se roban cuentas en cadena: primero la de ella, luego la tuya."},{"p":"Te llega un código de verificación que tú no pediste. Significa que…","ops":["Ganaste un premio","Tu celular está descompuesto","Alguien está intentando entrar a tu cuenta: no lo compartas y revisa tu seguridad"],"correcta":2,"explica":"Cambia tu contraseña si sospechas que la conocen y confirma que tienes activos los dos pasos."},{"p":"El PIN de verificación en dos pasos de WhatsApp debe ser…","ops":["El mismo NIP de tu tarjeta","Un número de 6 dígitos que solo tú conozcas, que no sea tu fecha de nacimiento","Tu fecha de nacimiento para no olvidarlo"],"correcta":1}]},{"tipo":"completar","rotulo":"Completa","items":[{"frase":"El código que te llega por SMS es la ___ de tu cuenta: nunca se comparte.","resp":["llave","clave"]},{"frase":"En WhatsApp, la verificación en dos pasos pide un PIN de ___ dígitos.","resp":["6","seis"]}]},{"tipo":"clave","items":["La verificación en dos pasos detiene a quien ya tiene tu contraseña.","Nunca compartas un código de verificación, aunque te lo pida alguien conocido.","Activa el PIN de WhatsApp y los dos pasos en tu correo y redes sociales hoy mismo."]}],"c-ciberseguridad-m2-l3":[{"tipo":"texto","texto":"Tu celular es tu cartera, tu álbum de fotos y tu oficina. Cuatro hábitos sencillos lo protegen de la mayoría de los problemas: <b>actualizar, respaldar, cuidar las redes Wi-Fi y revisar permisos</b>."},{"tipo":"pasos","rotulo":"Cinco hábitos básicos para tu celular","pasos":["<b>Actualiza</b> el sistema y las apps en cuanto haya versión nueva: muchas actualizaciones cierran fallas de seguridad que ya se conocen.","<b>Bloqueo de pantalla</b> con NIP de 6 dígitos, huella o rostro. Sin bloqueo, quien encuentre tu celular entra a todo.","<b>Respaldo automático</b> de fotos, contactos y chats en la nube de tu celular o en una computadora. Si te lo roban, pierdes el aparato, no tu vida.","<b>Descarga apps solo de la tienda oficial</b> (Google Play o App Store). Evita archivos .apk que te mandan por WhatsApp.","<b>Activa la función para localizar y borrar tu celular a distancia</b> (Encontrar mi dispositivo o Buscar)."]},{"tipo":"comparar","titulo":"Wi-Fi público: qué sí y qué no","malTitulo":"Arriesgado","mal":"Conectarte al Wi-Fi gratis de la plaza llamado «Internet_Gratis» y entrar a tu banca móvil o hacer una compra con tarjeta. Aceptar cualquier red abierta que aparezca.","bienTitulo":"Más seguro","bien":"Usar tus datos móviles para la banca y las compras. En Wi-Fi público, solo navegar en cosas sin datos sensibles y olvidar la red al terminar. Confirmar con el personal el nombre exacto de la red del lugar."},{"tipo":"tabla","titulo":"Permisos de apps: ¿tiene sentido?","encabezados":["App","Permiso razonable","Permiso sospechoso"],"filas":[["Linterna","Ninguno especial","Contactos, ubicación, micrófono"],["Mapa","Ubicación mientras la usas","Tus mensajes SMS"],["Préstamos","Cámara para tu identificación","Todos tus contactos y tu galería de fotos"],["Juego","Almacenamiento","Mensajes SMS, llamadas, accesibilidad"]],"nota":"Revisa los permisos en Ajustes, Aplicaciones o Privacidad. El permiso de <b>accesibilidad</b> le da a una app control casi total de tu celular: concédelo solo si sabes exactamente por qué lo necesita."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Estás en el café y necesitas transferir a tu hermana. Lo más seguro es…","ops":["Desconectarte del Wi-Fi público y usar tus datos móviles","Conectarte al Wi-Fi gratis del café","Pedirle al de la mesa de al lado su hotspot"],"correcta":0,"explica":"Tus datos móviles son una conexión que controlas tú."},{"p":"Una app de linterna pide acceso a tus contactos y mensajes. Debes…","ops":["Aceptar porque todas lo piden","Aceptar y revisar después","Negar el permiso o desinstalarla"],"correcta":2,"explica":"Si el permiso no tiene relación con lo que hace la app, desconfía."},{"p":"Para qué sirve el respaldo automático…","ops":["Para evitar recibir SMS falsos","Para no perder fotos, contactos y chats si pierdes o te roban el celular","Para que el celular vaya más rápido"],"correcta":1}]},{"tipo":"plantilla","rotulo":"Mi lista de revisión del celular","texto":"Mi lista de revisión del celular (hazla una vez al mes)\n\n[ ] Sistema y apps actualizados\n[ ] Bloqueo de pantalla con NIP de 6 dígitos, huella o rostro\n[ ] Respaldo automático activo y reciente\n[ ] Función de localizar y borrar a distancia activada\n[ ] Revisé permisos: contactos, galería, SMS, micrófono y accesibilidad\n[ ] Desinstalé apps que ya no uso\n[ ] Verificación en dos pasos activa en correo, WhatsApp y redes","nota":"Pon un recordatorio mensual en tu calendario, por ejemplo el primer domingo de cada mes."},{"tipo":"clave","items":["Actualiza, bloquea, respalda y descarga apps solo de la tienda oficial.","Para banca y compras, usa tus datos móviles, no el Wi-Fi público.","Revisa los permisos: si no tienen relación con lo que hace la app, niégalos."]}],"c-ciberseguridad-m2-pr":[{"tipo":"destacado","texto":"<b>El caso.</b> Don Ramiro tiene una taquería en Guadalajara que recibe la mitad de sus pedidos por WhatsApp Business. Su sobrina Karla le ayuda con Facebook e Instagram. El mes pasado a un taquero vecino le robaron el WhatsApp: el estafador pidió depósitos a sus clientes durante dos días y el negocio perdió pedidos y confianza. Don Ramiro le pide a Karla que dedique una tarde a <b>blindar las cuentas del negocio</b>. Tú la vas a acompañar. Calcula de 30 a 40 minutos."},{"tipo":"tabla","titulo":"Inventario de cuentas de la taquería","encabezados":["Cuenta","Quién la usa","¿Tiene dos pasos?","Prioridad"],"filas":[["WhatsApp Business del negocio","Don Ramiro y Karla","No","Alta: ahí llegan los pedidos y los pagos"],["Correo del negocio","Karla","No","Alta: recupera todas las demás cuentas"],["Facebook e Instagram","Karla","Solo Instagram","Media"],["Banca móvil del negocio","Don Ramiro","Sí (token en la app)","Alta, ya protegida"],["Cuenta de la app de entregas","Don Ramiro","No sabe","Media: revisar"]],"nota":"Empieza por el correo y por WhatsApp: si pierdes el correo, puedes perder todo lo que depende de él."},{"tipo":"pasos","rotulo":"Lo que hace Karla esa tarde","pasos":["Cambia la contraseña del <b>correo del negocio</b> por una frase larga y única, y activa en él la <b>verificación en dos pasos</b> desde la sección de seguridad de la cuenta.","Guarda los <b>códigos de respaldo</b> del correo (si el servicio los ofrece) impresos en un sobre, en el cajón con llave de la caja.","En WhatsApp Business entra a <b>Ajustes</b> → <b>Cuenta</b> → <b>Verificación en dos pasos</b> → <b>Activar</b> (así aparecen al momento de escribir), escribe un PIN de 6 dígitos que no sea fecha ni 123456 y agrega el correo del negocio.","Anota el PIN en el mismo sobre; solo lo conocen Don Ramiro y ella.","Activa los dos pasos en <b>Facebook</b> y revisa que sigan activos en <b>Instagram</b>, de preferencia con app autenticadora.","En cada cuenta revisa los <b>dispositivos conectados</b> y cierra sesión en los que no reconozca.","Pega junto a la caja la regla del negocio: «Aquí nadie comparte códigos, ni con la familia»."]},{"tipo":"ordenar","rotulo":"Ordena las palabras","items":[{"frase":"Primero protejo el correo que recupera todo","es":"Por qué el correo va antes que las redes"},{"frase":"El PIN de WhatsApp tiene seis dígitos","es":"Dato del segundo paso en WhatsApp"},{"frase":"Nadie comparte códigos ni con la familia","es":"La regla pegada junto a la caja"}]},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"Karla solo tiene tiempo para proteger una cuenta hoy. ¿Cuál elige primero?","ops":["Instagram, porque tiene más seguidores","El correo del negocio, porque con él se recuperan las demás cuentas","La app de entregas, porque es la más nueva"],"correcta":1,"explica":"Quien controla tu correo puede restablecer las contraseñas de casi todo lo demás."},{"p":"¿Dónde conviene guardar el PIN de WhatsApp y los códigos de respaldo?","ops":["En un sobre en un lugar seguro del negocio, fuera del celular","En un mensaje enviado a sí mismos por WhatsApp","En una nota pegada en la pantalla de la caja"],"correcta":0,"explica":"Si pierdes o te roban el celular, lo que guardaste solo ahí se va con él."},{"p":"Al revisar dispositivos conectados, Karla ve una sesión de Facebook abierta en una computadora de Tijuana que no conoce. ¿Qué hace?","ops":["Nada, puede ser un error de ubicación","Esperar a ver si publica algo raro","Cerrar esa sesión, cambiar la contraseña y confirmar que los dos pasos estén activos"],"correcta":2,"explica":"Una sesión que no reconoces se trata como intrusión hasta que se demuestre lo contrario."}]},{"tipo":"completar","rotulo":"Completa","items":[{"frase":"Los códigos de ___ sirven para entrar a tu cuenta si pierdes el celular.","resp":["respaldo","recuperación","recuperacion"]},{"frase":"Una app ___ genera códigos que cambian cada 30 segundos.","resp":["autenticadora","de autenticación","de autenticacion"]},{"frase":"Si veo una sesión que no reconozco, la ___ y cambio la contraseña.","resp":["cierro","cierra"]}]},{"tipo":"comparar","titulo":"La regla de los códigos en el negocio","mal":"«Karla, pásame el código que te llegó, es para entrar a la app de entregas desde mi celular.» Karla lo manda por WhatsApp sin preguntar, porque es su tío.","bien":"Don Ramiro y Karla acuerdan que los códigos no se dictan ni se reenvían: quien necesita entrar lo hace con su propio acceso o se sientan juntos frente al mismo celular."},{"tipo":"reflexion","rotulo":"Tu inventario","pregunta":"Haz tu propio inventario: escribe las cinco cuentas más importantes de tu negocio o de tu casa, quién las usa, si tienen dos pasos y cuál vas a proteger primero esta semana.","ayuda":"1. Correo principal: lo uso yo; dos pasos: no. Lo activo el…"},{"tipo":"clave","items":["Protege primero el correo: es la llave de recuperación de casi todas tus cuentas.","Activa el PIN de WhatsApp y guarda los códigos de respaldo fuera del celular.","En un negocio, la regla es simple: los códigos no se comparten, ni con la familia."]}],"c-ciberseguridad-m3-l1":[{"tipo":"texto","texto":"La banca móvil es, en general, más segura que andar con efectivo: puedes ver tus movimientos al momento, apagar tu tarjeta con un toque y recibir avisos de cada cargo. El riesgo no suele estar en la app, sino en que alguien te convenza de usarla <b>a favor de él</b>."},{"tipo":"tabla","titulo":"Lo que tu banco hace y lo que nunca hace","encabezados":["Tu banco SÍ puede…","Tu banco NUNCA te pide…"],"filas":[["Enviarte alertas de compras y transferencias","Tu NIP, contraseña de la app o clave de acceso"],["Llamarte para confirmar si reconoces una compra (con un sí o un no)","El código que te llegó por SMS, la clave dinámica o el número del token"],["Pedirte que llames tú al número del reverso de tu tarjeta","Que transfieras tu dinero a una «cuenta segura» o «cuenta espejo»"],["Mandarte avisos dentro de su app oficial","Que instales una app para «darte soporte» o que compartas tu pantalla"],["Bloquear tu tarjeta si detecta algo raro","Que le entregues tu tarjeta a un «mensajero» que pasará a recogerla"]],"nota":"Si una llamada te pide cualquier cosa de la columna derecha, cuelga. Aunque el número que aparece en tu pantalla sea el del banco: el identificador de llamadas se puede falsificar."},{"tipo":"pasos","rotulo":"Configura tu banca móvil hoy","pasos":["<b>Activa las alertas</b> por notificación de cada cargo, retiro y transferencia, sin importar el monto.","<b>Usa la tarjeta digital</b> para compras en línea: tiene un número distinto al de tu plástico y en muchos bancos su código de seguridad cambia o puedes apagarla cuando quieras.","<b>Pon límites</b> diarios a transferencias y compras en línea, acordes con lo que realmente usas.","<b>Apaga tu tarjeta</b> desde la app cuando no la uses, si tu banco lo permite.","<b>Entra siempre desde la app oficial</b> o escribiendo tú la dirección del banco, nunca desde un enlace."]},{"tipo":"comparar","titulo":"Llamada del «área de fraudes»","malTitulo":"Fraude","mal":"«Detectamos un intento de retiro. Para proteger su dinero vamos a moverlo a una cuenta segura a su nombre. Le dicto la CLABE; haga la transferencia mientras sigo en la línea.»","bienTitulo":"Lo que haría un banco legítimo","bien":"«Detectamos una operación inusual y bloqueamos temporalmente tu tarjeta. Para revisarla, llama al número de atención que viene al reverso de tu tarjeta o entra a tu app.» No te pide transferir nada ni te dicta cuentas."},{"tipo":"practica","rotulo":"¿Qué harías?","preguntas":[{"p":"Te llaman desde un número que aparece como el de tu banco y te piden la clave dinámica para «bloquear un cargo».","ops":["Colgar y llamar tú al número del reverso de tu tarjeta","Darla porque el número es el del banco","Dar solo los primeros tres dígitos"],"correcta":0,"explica":"El número en pantalla se puede falsificar; lo que nunca cambia es que el banco no pide claves."},{"p":"Un «asesor» te pide instalar una app para ayudarte a «cancelar un cargo» viendo tu pantalla.","ops":["Instalarla, porque así es más rápido","Instalarla y desinstalarla al terminar","Negarte y colgar: con esa app pueden ver y controlar tu celular"],"correcta":2,"explica":"Las apps de control remoto permiten ver tus claves y operar tu banca."},{"p":"Para comprar en línea conviene usar…","ops":["La tarjeta de débito donde tienes tu nómina completa sin alertas","La tarjeta digital, con alertas activas","La tarjeta física y mandar foto de ambos lados"],"correcta":1}]},{"tipo":"clave","items":["Tu banco nunca te pide NIP, contraseñas, códigos ni que muevas tu dinero a una «cuenta segura».","Alertas activas, límites razonables y tarjeta digital para comprar en línea.","Si dudas, cuelga y llama tú al número del reverso de tu tarjeta."]}],"c-ciberseguridad-m3-l2":[{"tipo":"texto","texto":"En México puedes enviar dinero por <b>SPEI</b> (el sistema de transferencias del Banco de México, con CLABE de 18 dígitos, tarjeta de débito o número de cuenta), por <b>DiMo</b> (usando el número de celular del destinatario, ligado a su cuenta) o cobrar con <b>CoDi</b> (con un código QR). Son rápidos y cómodos, pero hay que saber algo clave: <b>una transferencia enviada, en general, no se puede cancelar</b>. Si te engañaron o te equivocaste de cuenta, avisa de inmediato a tu banco, pero no cuentes con recuperarla."},{"tipo":"pasos","rotulo":"Antes de tocar «Enviar», revisa","pasos":["<b>¿A quién le pago y por qué?</b> Si es alguien que conociste hace una hora en redes, detente.","<b>El nombre del titular</b> que te muestra la app: ¿coincide con la persona o el negocio que esperas? Si el vendedor se llama Laura y la cuenta es de «Jorge R.», pregunta antes de pagar.","<b>El monto</b>: revisa ceros y decimales.","<b>El concepto</b>: escribe algo claro («Renta octubre depto 3») para tu comprobante.","<b>La presión</b>: si te apuran para pagar «antes de que se lo gane otro», es una señal de alarma.","<b>Guarda el comprobante</b> y la conversación: te servirán si hay un problema."]},{"tipo":"destacado","texto":"<b>Al momento de escribir</b>, el Banco de México actualizó las reglas para que las apps bancarias ofrezcan más formas de identificar al destinatario (CLABE, tarjeta, celular con DiMo o código QR) y muestren sus datos para revisarlos antes de confirmar. Los menús pueden verse distintos según tu banco; la regla sigue siendo la misma: <b>lee el nombre del titular antes de enviar</b>."},{"tipo":"comparar","titulo":"Compra en línea","malTitulo":"Señales de tienda falsa","mal":"Precios 60% más baratos que en todos lados. Solo aceptan transferencia o depósito en tienda de conveniencia. Página creada hace semanas, sin dirección ni teléfono, con reseñas copiadas. Te contactan por mensaje directo.","bienTitulo":"Hábitos de compra segura","bien":"Compra en tiendas conocidas o en plataformas que ofrezcan protección al comprador. Paga con tarjeta digital o de crédito (es más fácil aclarar un cargo). Escribe tú la dirección de la tienda. Busca opiniones de otros compradores y datos de contacto reales."},{"tipo":"relacionar","rotulo":"¿Qué es cada cosa?","pares":[["Clave de 18 dígitos para transferir","CLABE"],["Enviar dinero con el número de celular del destinatario","DiMo"],["Cobrar o pagar escaneando un código QR","CoDi"],["Sistema de transferencias inmediatas del Banco de México","SPEI"],["Número distinto al de tu plástico para comprar en línea","Tarjeta digital"]]},{"tipo":"practica","rotulo":"Casos","preguntas":[{"p":"Vas a pagar un anticipo de $2,000 por una estufa usada. La app muestra que la cuenta es de un nombre distinto al del vendedor.","ops":["Preguntar y, si no hay una explicación clara, no pagar","Pagar, porque el nombre no importa","Pagar la mitad para probar"],"correcta":0,"explica":"Muchos fraudes usan cuentas de terceros para cobrar."},{"p":"Transferiste por error a una CLABE equivocada. Lo primero es…","ops":["Esperar a ver si regresa solo","Hacer otra transferencia para compensar","Llamar de inmediato a tu banco y reportarlo"],"correcta":2,"explica":"Entre más rápido lo reportes, más opciones tendrá el banco de ayudarte."},{"p":"Una tienda en redes solo acepta depósitos en tienda de conveniencia y tiene precios muy bajos. Es…","ops":["Garantía de buen precio","Una señal de probable fraude","Normal en cualquier tienda"],"correcta":1}]},{"tipo":"clave","items":["Una transferencia enviada, en general, no se puede cancelar: revisa antes de enviar.","Lee el nombre del titular, el monto y el concepto; desconfía de la prisa.","Compra en tiendas conocidas y paga con tarjeta digital o de crédito."]}],"c-ciberseguridad-m3-l3":[{"tipo":"texto","texto":"Si ves un cargo que no hiciste, <b>el tiempo corre a tu favor solo si actúas rápido</b>. Los delincuentes suelen hacer primero un cargo pequeño de «prueba» (de $1 o $10) y, si nadie reclama, luego uno grande. Por eso conviene revisar tus movimientos cada semana, no solo cuando llega el estado de cuenta."},{"tipo":"pasos","rotulo":"Qué hacer ante un cargo no reconocido","pasos":["<b>Bloquea la tarjeta de inmediato</b> desde la app o llamando al número del reverso.","<b>Presenta la aclaración con tu banco</b> (en la app, por teléfono, en sucursal o en su Unidad Especializada de Atención a Usuarios, UNE). Pide y guarda el <b>número de folio</b>, la fecha y la hora.","<b>Respeta el plazo:</b> tienes <b>90 días naturales</b> para presentar la aclaración, contados desde la fecha de corte o de la operación. No esperes al último día.","<b>Espera la respuesta del banco:</b> tiene un plazo máximo de <b>45 días</b> para responder en operaciones nacionales. Mientras dure la aclaración, no deben reportarte como moroso por ese monto.","<b>Si no se resuelve o no estás de acuerdo</b>, acude a la <b>CONDUSEF</b> con tu folio y tus pruebas."]},{"tipo":"destacado","texto":"<b>CONDUSEF</b> (Comisión Nacional para la Protección y Defensa de los Usuarios de Servicios Financieros) te orienta gratis y recibe quejas contra bancos y otras instituciones financieras. Al momento de escribir, su Centro de Atención Telefónica es el <b>55 5340 0999</b> y tiene portal de queja electrónica en condusef.gob.mx. Los plazos y condiciones pueden variar según el producto y el monto: verifica tu caso con tu banco o con CONDUSEF."},{"tipo":"excel","rotulo":"Revisa tus movimientos de septiembre","datos":[["Fecha","Comercio","Monto","¿Lo reconozco?","Acción","","Resumen","Valor"],["02/09","Supermercado La Esperanza",856.4,"Sí","","","Cargos no reconocidos",""],["03/09","Gasolinera Ruta 57",700,"Sí","OK","","Monto a aclarar",""],["04/09","PAGO WEB XJ SERV",1,"No","","","¿Qué hago hoy?",""],["04/09","PAGO WEB XJ SERV",4890,"No","Reportar al banco"],["06/09","Farmacia del Centro",312.5,"Sí","OK"],["07/09","Suscripción de películas",139,"Sí","OK"],["08/09","TIENDA ONLINE INTL",2350,"No","Reportar al banco"]],"retos":[{"celda":"E2","formula":"=SI(D2=\"No\",\"Reportar al banco\",\"OK\")","esperado":"OK","requiere":"SI(","texto":"<b>E2</b>: escribe una fórmula que diga «Reportar al banco» SI en D2 dice «No»; si no, «OK».","pista":"=SI(D2=\"No\",\"Reportar al banco\",\"OK\")"},{"celda":"E4","formula":"=SI(D4=\"No\",\"Reportar al banco\",\"OK\")","esperado":"Reportar al banco","requiere":"SI(","texto":"<b>E4</b>: aplica la misma fórmula al cargo de $1.","explica":"Ese cargo de $1 parece inofensivo, pero suele ser una «prueba» antes del cargo grande del mismo día."},{"celda":"H2","formula":"=CONTAR.SI(D2:D8,\"No\")","esperado":3,"requiere":"CONTAR.SI(","texto":"<b>H2</b>: cuenta cuántos movimientos NO reconoces. Usa CONTAR.SI sobre la columna D.","pista":"=CONTAR.SI(D2:D8,\"No\")"},{"celda":"H3","formula":"=SUMAR.SI(D2:D8,\"No\",C2:C8)","esperado":7241,"requiere":"SUMAR.SI(","texto":"<b>H3</b>: suma el monto de los cargos que NO reconoces con SUMAR.SI.","pista":"=SUMAR.SI(rango del criterio,\"No\",rango de montos)"},{"celda":"H4","formula":"=SI(H2>0,\"Bloquear tarjeta y aclarar\",\"Todo en orden\")","esperado":"Bloquear tarjeta y aclarar","requiere":"SI(","texto":"<b>H4</b>: SI hay al menos un cargo no reconocido (H2 mayor que 0), que diga «Bloquear tarjeta y aclarar»; si no, «Todo en orden».","explica":"Con $7,241 en tres cargos no reconocidos, hoy mismo hay que bloquear la tarjeta y presentar la aclaración con folio."}]},{"tipo":"tabla","titulo":"Otras herramientas que te protegen","encabezados":["Herramienta","Para qué sirve","Dónde"],"filas":[["<b>REUS</b> (Registro Público de Usuarios)","Inscribes tu teléfono o correo para que las instituciones financieras no te envíen publicidad. Si después de inscribirte te «ofrecen» un crédito por teléfono, desconfía todavía más.","CONDUSEF, en línea o por teléfono"],["<b>Reporte de Crédito Especial</b>","Ver qué créditos aparecen a tu nombre y detectar si alguien sacó uno con tus datos. Puedes pedirlo gratis una vez cada 12 meses.","Buró de Crédito y Círculo de Crédito"],["<b>SIPRES</b> (Registro de Prestadores de Servicios Financieros)","Consultar si una empresa de préstamos o una financiera está registrada.","CONDUSEF"]],"nota":"Verifica en los sitios oficiales los requisitos, la vigencia y el tiempo que tarda en surtir efecto cada trámite."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Ves un cargo de $1 de un comercio que no conoces. Lo mejor es…","ops":["Bloquear la tarjeta y reportarlo, porque puede ser una prueba antes de un cargo mayor","Ignorarlo por ser poco dinero","Esperar al siguiente estado de cuenta"],"correcta":0,"explica":"Los cargos de prueba anuncian el fraude grande."},{"p":"Para presentar la aclaración de un cargo no reconocido tienes…","ops":["5 días hábiles","Un año","90 días naturales"],"correcta":2,"explica":"Cuentan desde la fecha de corte o de la operación; mejor hazlo el mismo día."},{"p":"Si tu banco no resuelve tu aclaración, puedes acudir a…","ops":["El SAT","La CONDUSEF","La PROFECO"],"correcta":1,"explica":"CONDUSEF atiende a usuarios de servicios financieros; PROFECO, a consumidores de bienes y servicios en general."},{"p":"Para saber si alguien sacó un crédito a tu nombre, revisas…","ops":["Tu Reporte de Crédito Especial","Tu estado de cuenta de la luz","Tu constancia de situación fiscal"],"correcta":0}]},{"tipo":"clave","items":["Bloquea, presenta la aclaración con folio y hazlo cuanto antes: el plazo es de 90 días naturales y el banco responde en máximo 45 días.","Si el banco no resuelve, acude a CONDUSEF con tu folio y tus pruebas.","Revisa tus movimientos cada semana, inscríbete al REUS y consulta tu reporte de crédito al menos una vez al año."]}],"c-ciberseguridad-m4-l1":[{"tipo":"texto","texto":"Si caíste, no eres tonto ni descuidado: estas estafas están diseñadas por gente que se dedica a eso todo el día y le pasan a personas de todas las edades y profesiones. La vergüenza es la mejor aliada del estafador, porque hace que la gente tarde en pedir ayuda. <b>Lo que importa ahora es actuar rápido y en orden.</b>"},{"tipo":"pasos","rotulo":"Pasos inmediatos","pasos":["<b>Bloquea tus tarjetas</b> desde la app o llamando al número del reverso. Si diste datos de acceso, pide también que bloqueen la banca en línea.","<b>Cambia contraseñas</b> empezando por tu correo, luego banca y redes sociales, desde un dispositivo que sea tuyo y de confianza. Cierra las sesiones abiertas en otros equipos.","<b>Activa la verificación en dos pasos</b> donde aún no la tengas.","<b>Recupera tu WhatsApp</b> si te lo robaron: reinstálalo e inicia sesión con tu número para recibir tu propio código.","<b>Avisa a tus contactos</b> por otro medio (llamada, SMS o redes) que no atiendan pedidos de dinero desde tu cuenta.","<b>Junta evidencia:</b> capturas de pantalla de mensajes, números, perfiles, comprobantes de transferencia y folios del banco.","<b>Presenta la aclaración</b> con tu banco y, si corresponde, la denuncia (lo verás en la siguiente lección)."]},{"tipo":"tabla","titulo":"Según lo que pasó","encabezados":["Si…","Haz esto primero"],"filas":[["Diste datos de tu tarjeta en una página falsa","Bloquea la tarjeta, pide una nueva y revisa tus movimientos de los últimos días"],["Dictaste un código o la clave dinámica por teléfono","Llama de inmediato a tu banco por el número oficial; bloquea tarjetas y banca en línea"],["Te robaron el WhatsApp","Reinstala y verifica tu número; avisa a tus contactos por otro medio. Si el delincuente activó un PIN, WhatsApp puede pedirte esperar antes de reactivarlo: consulta su centro de ayuda"],["Transferiste dinero a un estafador","Reporta de inmediato a tu banco con los datos de la cuenta destino y guarda el comprobante; después, denuncia"],["Diste copia de tu INE o datos personales","Revisa tu reporte de crédito, vigila tus cuentas y considera denunciar para dejar constancia"]]},{"tipo":"destacado","texto":"<b>Cuidado con la segunda estafa:</b> después de un fraude, a veces aparecen «abogados» o «hackers» que prometen recuperar tu dinero a cambio de un pago por adelantado. Es otro fraude. Las gestiones legítimas se hacen con tu banco, con CONDUSEF y con las autoridades."},{"tipo":"ordenar","rotulo":"Ordena la prioridad","items":[{"frase":"Primero bloquea tarjetas y después cambia contraseñas","es":"Detener el daño va antes que todo"}]},{"tipo":"practica","rotulo":"Casos","preguntas":[{"p":"Don Ernesto le dictó la clave dinámica a un falso asesor del banco hace diez minutos. Lo primero que debe hacer es…","ops":["Esperar a ver si le cargan algo","Llamarle de vuelta al asesor para reclamarle","Llamar al número oficial de su banco para bloquear tarjetas y banca en línea"],"correcta":2,"explica":"Cada minuto cuenta: el estafador puede estar operando en ese momento."},{"p":"A Sofía le robaron el WhatsApp y sus contactos reciben pedidos de dinero. Además de recuperarlo, debe…","ops":["Borrar su cuenta de correo","Avisar a sus contactos por otro medio que no depositen","Esperar a que el estafador se aburra"],"correcta":1,"explica":"Una publicación en redes o SMS a sus contactos cercanos frena el daño en cadena."},{"p":"Alguien te ofrece recuperar tu dinero robado a cambio de un pago de $3,000 por adelantado. Es…","ops":["Probablemente una segunda estafa","Un servicio del banco","Obligatorio para recuperar el dinero"],"correcta":0}]},{"tipo":"clave","items":["Caer no es motivo de vergüenza; actuar rápido sí hace la diferencia.","Bloquea tarjetas, cambia contraseñas empezando por el correo, recupera WhatsApp y avisa a tus contactos.","Junta evidencia y desconfía de quien cobra por adelantado para «recuperar» tu dinero."]}],"c-ciberseguridad-m4-l2":[{"tipo":"texto","texto":"Denunciar sirve para dejar constancia, para que las autoridades conozcan los números y cuentas que usan los delincuentes y, en algunos casos, para respaldar tus trámites con el banco o con CONDUSEF. No todos los canales sirven para lo mismo: conviene saber cuál usar."},{"tipo":"tabla","titulo":"¿A qué número o institución acudo?","encabezados":["Canal","Para qué sirve"],"filas":[["<b>911</b>","Emergencias: si hay riesgo para tu vida o la de alguien, o una extorsión o secuestro en curso."],["<b>089</b>","Denuncia anónima: puedes reportar extorsiones y otros delitos sin dar tu nombre."],["<b>088</b>","Atención ciudadana de la Guardia Nacional (SSPC). La SSPC también lo indica para contactar a la Policía Cibernética y reportar delitos en internet."],["<b>Policía Cibernética de tu estado</b>","Orientación y reportes sobre fraudes y delitos en internet. Por ejemplo, en la Ciudad de México atiende en el 55 5242 5100, extensión 5086, al momento de escribir."],["<b>Fiscalía o Ministerio Público</b>","Denuncia formal del delito (fraude, extorsión, robo de identidad). Muchas fiscalías permiten iniciarla en línea."],["<b>Tu banco y CONDUSEF</b>","Aclaraciones y quejas por cargos o transferencias (módulo 3)."]],"nota":"Los teléfonos, extensiones y servicios en línea cambian por estado y con el tiempo: verifica los datos de la Policía Cibernética y de la Fiscalía de tu entidad en sus sitios oficiales."},{"tipo":"pasos","rotulo":"Si recibes una llamada de extorsión","pasos":["<b>No sigas la conversación ni des datos:</b> los extorsionadores buscan que tú les digas nombres y detalles.","<b>Cuelga</b>, aunque te digan que no lo hagas.","<b>Localiza a tu familiar</b> llamándole directamente o a alguien que esté con él. Usa la palabra clave familiar (lo verás en la siguiente lección).","<b>No deposites</b> ni compres tarjetas de tiempo aire o de regalo.","<b>Reporta</b> al 089 de forma anónima o al 911 si crees que hay un riesgo real."]},{"tipo":"plantilla","rotulo":"Datos para llevar a tu denuncia","texto":"Datos para mi denuncia\n\nQué pasó (en orden y con horas aproximadas):\nFecha y hora:\nNúmeros de teléfono, perfiles o correos que me contactaron:\nPáginas o enlaces que usaron:\nMonto perdido y medio de pago:\nCuenta, CLABE o tarjeta a la que envié dinero:\nFolio de aclaración con mi banco:\nCapturas de pantalla y comprobantes (guardados en):\nIdentificación oficial vigente","nota":"Guarda la evidencia antes de borrar chats o bloquear números. Haz capturas donde se vea la fecha, la hora y el número."},{"tipo":"relacionar","rotulo":"Relaciona la situación con el canal","pares":[["Te llaman diciendo que tienen a tu hijo y él no contesta","911"],["Quieres reportar un número de extorsión sin dar tu nombre","089"],["Quieres presentar la denuncia formal por fraude","Fiscalía o Ministerio Público"],["Tu banco no resolvió tu aclaración","CONDUSEF"]]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Durante una llamada de extorsión, lo más recomendable es…","ops":["Seguir la llamada para dar información","Depositar una parte para ganar tiempo","Colgar y localizar a tu familiar por otro medio"],"correcta":2,"explica":"Mientras más hables, más datos obtienen para presionarte."},{"p":"El 089 sirve para…","ops":["Aclarar cargos de tu tarjeta","Denunciar de forma anónima","Pedir una ambulancia"],"correcta":1,"explica":"Para emergencias en curso, el 911."},{"p":"Antes de borrar chats y bloquear al estafador, conviene…","ops":["Hacer capturas de pantalla con fecha, hora y número","Responderle con insultos","Reenviar los mensajes a todos tus contactos"],"correcta":0}]},{"tipo":"clave","items":["911 para emergencias; 089 para denuncia anónima; 088 y la Policía Cibernética de tu estado para delitos en internet.","La denuncia formal se presenta ante la Fiscalía o el Ministerio Público; lleva tu evidencia ordenada.","Ante una extorsión: cuelga, localiza a tu familiar y no deposites."]}],"c-ciberseguridad-m4-l3":[{"tipo":"texto","texto":"Los estafadores buscan a quien está menos informado o más solo: adultos mayores que no conocen bien las apps, adolescentes que confían en desconocidos en juegos y redes, o cualquiera en un momento de prisa. La mejor protección es <b>hablarlo en familia antes de que pase</b> y ponerse de acuerdo en qué hacer."},{"tipo":"tarjetas","rotulo":"Qué hablar con cada quien","tarjetas":[{"frente":"<b>Adultos mayores</b>","reverso":"Que el banco nunca pide claves ni códigos; que ante cualquier llamada rara cuelguen y te llamen; ayúdales a activar alertas y el bloqueo de pantalla, sin quitarles su independencia."},{"frente":"<b>Niños</b>","reverso":"No dar su nombre completo, escuela ni dirección a desconocidos; no aceptar regalos de dinero o recompensas en juegos a cambio de fotos o datos; avisar a un adulto si algo les da miedo o incomodidad."},{"frente":"<b>Adolescentes</b>","reverso":"Perfiles privados, cuidado con lo que publican (uniforme, ubicación en tiempo real) y con ofertas de trabajo «fácil»; que sepan que pueden contarte si algo salió mal sin que los regañes."},{"frente":"<b>Todos</b>","reverso":"Nadie comparte códigos. Nadie deposita por una llamada o mensaje sin confirmar antes con la familia."}]},{"tipo":"destacado","texto":"<b>La palabra clave familiar</b> es una palabra o frase que solo conoce tu familia y que no aparece en redes sociales (nada de nombres de mascotas ni fechas). Si alguien llama o escribe diciendo ser tu hijo, tu mamá o tu hermano y pide dinero o ayuda urgente, le preguntas la palabra clave. Si no la sabe, cuelgas y llamas al número de siempre."},{"tipo":"comparar","titulo":"Llamada «de tu nieto»","malTitulo":"Sin plan","mal":"Abuela: «¿Beto? ¿Eres tú?». Estafador: «Sí, abue, soy Beto. Choqué y me detuvieron; no le digas a mi papá. Deposita $8,000 al licenciado.» La abuela, asustada, deposita.","bienTitulo":"Con plan","bien":"Abuela: «¿Quién habla?». Estafador: «Soy tu nieto, abue, choqué…». Abuela: «Dime la palabra de la familia.» El estafador inventa algo. La abuela cuelga, llama a Beto a su número de siempre y reporta el número al 089."},{"tipo":"plantilla","rotulo":"Plan de seguridad de mi familia","texto":"Plan de seguridad de la familia ___________\n\nPalabra clave (no escribirla en el celular ni en redes): la acordamos en persona\nA quién llamamos si hay una llamada rara: ___________ (tel. de siempre)\nReglas:\n1. Nadie comparte códigos, NIP ni contraseñas, con nadie.\n2. Nadie deposita por una llamada o mensaje sin confirmar con otro familiar.\n3. Si alguien dice «cambié de número», llamamos al número anterior.\n4. Colgar está permitido: no es de mala educación.\n5. Si alguien cae, lo ayudamos sin regaños y actuamos rápido.\nTeléfonos útiles: banco (reverso de la tarjeta), 911, 089, CONDUSEF 55 5340 0999","nota":"Revisen el plan juntos cada seis meses o cuando alguien estrene celular."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Una buena palabra clave familiar es…","ops":["El nombre del perro, que todos conocen","La fecha de cumpleaños de la abuela","Una frase que solo conoce la familia y no aparece en redes"],"correcta":2,"explica":"Todo lo que publicas en redes lo puede investigar un estafador."},{"p":"Tu hijo de 11 años te cuenta que alguien en un juego le ofreció monedas a cambio de fotos. Lo mejor es…","ops":["Ignorarlo, porque es solo un juego","Agradecerle que te contó, guardar evidencia, bloquear y reportar al contacto en la plataforma","Castigarlo sin videojuegos para siempre"],"correcta":1,"explica":"Si lo regañas, la próxima vez quizá no te cuente. Si hubo solicitud de fotos íntimas o amenazas, denuncia ante las autoridades."},{"p":"Para ayudar a un adulto mayor con su celular, conviene…","ops":["Activar con él alertas, bloqueo de pantalla y verificación en dos pasos, explicándole cada paso","Quitarle la banca móvil sin avisar","Guardar tú todas sus contraseñas en un papel en su cartera"],"correcta":0}]},{"tipo":"reflexion","rotulo":"Tu lista de verificación personal","pregunta":"De todo lo que viste en el curso, ¿cuáles son las tres acciones que vas a hacer esta semana? Por ejemplo: activar el PIN de WhatsApp, cambiar la contraseña de tu correo, activar alertas en tu banca, inscribirte al REUS o acordar la palabra clave familiar.","ayuda":"Esta semana voy a: 1)… 2)… 3)… Y voy a platicar el plan con…"},{"tipo":"clave","items":["Habla de seguridad en familia antes de que pase; colgar está permitido.","Acuerden una palabra clave que no esté en redes y confirmen siempre por el número de siempre.","Adultos mayores, niños y adolescentes necesitan acuerdos distintos, sin regaños y con confianza."]}],"c-ciberseguridad-m4-pr":[{"tipo":"destacado","texto":"<b>El caso.</b> Lety tiene una estética en Toluca. Un martes a mediodía suena el teléfono del local: un hombre, con tono amenazante, dice que «tiene vigilado el negocio», que sabe que su hijo Emilio sale de la prepa a las dos y que, si no deposita $15,000 en la próxima hora, «algo le va a pasar». Le exige no colgar. Lety tiene una clienta en la silla y a su mamá, doña Chelo, de 72 años, en la recepción. Calcula de 30 a 40 minutos."},{"tipo":"texto","texto":"La mayoría de estas llamadas son <b>extorsiones a distancia</b>: quien llama no tiene a nadie ni está cerca. Su única arma es el miedo y que no cuelgues, para que no puedas comprobar que tu familiar está bien. Por eso los datos que dan (un nombre, una escuela, un horario) suelen salir de redes sociales o de lo que tú misma les dices en la conversación.<br><br>Recuerda los números: <b>911</b> para emergencias o si crees que hay un riesgo real; <b>089</b> para denunciar de forma anónima, incluida la extorsión; <b>088</b> para la atención ciudadana de la Guardia Nacional. Si además hubo un cargo o una transferencia, tu banco y la <b>CONDUSEF</b> (al momento de escribir, 55 5340 0999) te orientan con la aclaración."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"El hombre insiste en que Lety no cuelgue. ¿Qué es lo primero que le conviene hacer?","ops":["Seguir en la línea para no provocarlo","Colgar y llamar directamente a Emilio o a alguien que esté con él","Negociar una cantidad menor"],"correcta":1,"explica":"Mantenerte en la línea es parte del truco: te impide comprobar que tu familiar está bien."},{"p":"Emilio no contesta porque está en clase. ¿Qué hace Lety?","ops":["Llamar a la escuela o a otro contacto que pueda confirmar que está bien, y reportar al 911 si sigue la duda","Depositar para no arriesgarse","Volver a marcar al extorsionador para pedirle una prueba"],"correcta":0,"explica":"Un segundo contacto de confianza (escuela, amigo, otro familiar) está en el plan familiar justo para este momento."},{"p":"Ya confirmó que Emilio está bien. Para reportar la llamada sin dar su nombre, marca al…","ops":["088","089","911"],"correcta":1,"explica":"El 089 es la línea de denuncia anónima. El 911 es para emergencias en curso."},{"p":"Al día siguiente llega otro mensaje: «Sabemos dónde está tu local». ¿Qué conviene?","ops":["Contestar para demostrar que no tiene miedo","Borrar el mensaje y olvidarlo","No contestar, guardar capturas con fecha y número, y reportarlo"],"correcta":2,"explica":"Las capturas sirven como evidencia si decides denunciar. Contestar solo les da más información."}]},{"tipo":"tarjetas","rotulo":"Qué hacer y qué no, en voz alta","tarjetas":[{"frente":"«No cuelgue o le va peor.»","reverso":"Cuelga. Tu prioridad es localizar a tu familiar por otro medio."},{"frente":"«Dígame cómo se llama su hijo.»","reverso":"No des nombres ni datos: ellos buscan que tú los completes."},{"frente":"«Compre tarjetas de tiempo aire y dícteme los números.»","reverso":"No compres ni dictes nada. Es una forma de pago que no se recupera."},{"frente":"«Ya sabemos dónde vive.»","reverso":"Guarda el número y la hora, y repórtalo al 089 o al 911 si hay riesgo."},{"frente":"«Soy tu nieto, abue, no le digas a nadie.»","reverso":"Pide la palabra clave familiar. Si no la sabe, cuelga y llama a tu nieto."}]},{"tipo":"relacionar","rotulo":"¿A dónde acudo?","pares":[["Crees que hay un riesgo real en este momento","911"],["Quieres denunciar una extorsión sin dar tu nombre","089"],["Atención ciudadana de la Guardia Nacional","088"],["El banco no resolvió tu aclaración por un cargo","CONDUSEF"],["Quieres presentar una denuncia formal","Fiscalía o Ministerio Público"]]},{"tipo":"comparar","titulo":"Doña Chelo contesta el teléfono","mal":"«¿Emilio? ¿Mi nieto Emilio, el de la prepa de la avenida? ¿Qué le pasó?» Sin querer, le confirmó al extorsionador el nombre y la escuela.","bien":"«¿Quién habla? … No doy información por teléfono.» Cuelga, avisa a Lety y juntas siguen el plan: localizar a Emilio, guardar el número y reportar."},{"tipo":"reflexion","rotulo":"Tu plan familiar","pregunta":"Escribe el plan de tu familia para una llamada de extorsión: quién llama a quién, un segundo contacto por cada persona (escuela, trabajo, amigo), dónde está anotado y qué número marcan si no localizan a alguien.","ayuda":"Si llaman diciendo que tienen a ___, yo cuelgo y marco a ___. Si no contesta, llamo a ___…"},{"tipo":"plantilla","rotulo":"Tarjeta para la recepción del negocio","texto":"SI LLAMAN PARA AMENAZAR O PEDIR DINERO\n1. No des nombres, horarios ni datos de nadie.\n2. Cuelga, aunque insistan.\n3. Avisa a [nombre del responsable] y localicen a la persona mencionada: [teléfono] / segundo contacto: [teléfono].\n4. Anota número, hora y lo que dijeron. No borres mensajes.\n5. Riesgo real: 911. Denuncia anónima: 089.\nPalabra clave de la familia: la sabes tú, no la escribas aquí.","nota":"Cópiala, adáptala y pégala junto al teléfono del negocio o de la casa."},{"tipo":"clave","items":["En una extorsión telefónica, colgar y localizar a tu familiar por otro medio es lo primero.","911 para riesgo real, 089 para denuncia anónima, 088 para la Guardia Nacional.","Un plan familiar escrito, con segundos contactos y palabra clave, quita el poder al miedo."]}]},"q":{"c-ciberseguridad-m1":[{"p":"¿Qué es la ingeniería social?","ops":["Un tipo de antivirus","Una carrera universitaria de sistemas","Un fraude que solo ocurre en computadoras","Manipular a una persona para que entregue datos, códigos o dinero"],"correcta":3},{"p":"«Su cuenta se bloquea en 30 minutos» usa principalmente la palanca de…","ops":["Confianza","Curiosidad","Urgencia","Premio"],"correcta":2},{"p":"Tu banco te llama y te pide el código que te llegó por SMS. Lo correcto es…","ops":["Mandárselo por WhatsApp en vez de decirlo","Colgar y llamar tú al número del reverso de tu tarjeta","Dárselo si saben tu nombre","Dárselo si la llamada suena profesional"],"correcta":1},{"p":"El código de 6 dígitos de WhatsApp sirve para…","ops":["Activar tu cuenta en otro teléfono, por eso nunca se comparte","Ganar premios","Confirmar un pedido","Nada importante"],"correcta":0},{"p":"Una señal típica de oferta falsa en Marketplace es…","ops":["Que el vendedor acepte verse en un lugar público","Que puedas revisar el producto antes de pagar","Que el anuncio tenga varias fotos","Precio muy bajo y prisa por que pagues un apartado antes de ver el producto"],"correcta":3},{"p":"Un «empleo» te pide pagar un kit antes de empezar. Es…","ops":["Obligatorio por ley","Señal de que el sueldo es alto","Una señal de falso empleo","Normal en cualquier trabajo formal"],"correcta":2},{"p":"Para verificar un mensaje sospechoso de tu banco, lo más seguro es…","ops":["Llamar al número que viene en el mensaje","Entrar a la app oficial o llamar al número del reverso de tu tarjeta","Usar el enlace del mensaje","Responder el SMS con tus datos"],"correcta":1},{"p":"Un número nuevo con la foto de tu hija te pide dinero urgente. Primero…","ops":["Llamas a su número de siempre para confirmar","Depositas y luego preguntas","Le pides que te mande otra foto","Reenvías el mensaje a toda la familia"],"correcta":0}],"c-ciberseguridad-m2":[{"p":"Lo que más hace fuerte a una contraseña es…","ops":["Que tenga tu fecha de nacimiento","Que sea la misma en todas tus cuentas","Que sea corta para no olvidarla","Que sea larga y única"],"correcta":3},{"p":"¿Por qué es riesgoso repetir la misma contraseña?","ops":["Porque ocupa espacio en el celular","No es riesgoso","Porque si se filtra en un sitio, abren tus otras cuentas","Porque el banco la cancela"],"correcta":2},{"p":"Un gestor de contraseñas sirve para…","ops":["Recibir SMS del banco","Crear, guardar y rellenar contraseñas distintas para cada cuenta","Hackear cuentas ajenas","Acelerar el internet"],"correcta":1},{"p":"La verificación en dos pasos protege porque…","ops":["Pide algo más que tu contraseña para entrar","Borra tus datos cada semana","Te avisa de ofertas","Cambia tu número de teléfono"],"correcta":0},{"p":"Un conocido te pide el código de 6 dígitos que te llegó. Lo correcto es…","ops":["Compartirlo si es de confianza","Compartirlo por mensaje de voz","Compartirlo solo la mitad","No compartirlo y llamarle por teléfono para advertirle"],"correcta":3},{"p":"Para hacer una transferencia fuera de casa, es más seguro usar…","ops":["Cualquier red abierta","El Wi-Fi de un desconocido","Tus datos móviles","El Wi-Fi gratis de la plaza"],"correcta":2},{"p":"Una app de préstamos pide acceso a tus contactos y galería. Es señal de…","ops":["Mayor seguridad","Riesgo: podrían usarlos para presionarte o exhibirte","Buena atención al cliente","Requisito legal"],"correcta":1},{"p":"Instalar apps desde archivos que te mandan por WhatsApp es…","ops":["Riesgoso: descarga apps solo de la tienda oficial","Más rápido y seguro","Recomendado por los bancos","Igual que descargarlas de la tienda"],"correcta":0}],"c-ciberseguridad-m3":[{"p":"¿Cuál de estos datos te puede pedir tu banco por teléfono?","ops":["Tu NIP","El código que te llegó por SMS","Tu contraseña de la app","Que confirmes si reconoces una compra, con un sí o un no"],"correcta":3},{"p":"Una «cuenta segura» a la que te piden mover tu dinero para protegerlo es…","ops":["Una cuenta del Banco de México","Obligatoria ante un cargo sospechoso","Un fraude: el banco nunca te pide eso","Un servicio normal del banco"],"correcta":2},{"p":"Antes de enviar una transferencia, lo más importante es revisar…","ops":["Que el vendedor tenga foto de perfil","El nombre del titular, el monto y a quién le pagas","El color de la app","La hora del día"],"correcta":1},{"p":"DiMo permite…","ops":["Enviar dinero usando el número de celular del destinatario","Cancelar cualquier transferencia enviada","Consultar tu reporte de crédito","Bloquear llamadas de publicidad"],"correcta":0},{"p":"Para compras en línea, conviene usar…","ops":["Depósitos en tienda de conveniencia a desconocidos","Transferencias a cuentas personales de vendedores en redes","La tarjeta física enviando foto de ambos lados","La tarjeta digital o de crédito, con alertas"],"correcta":3},{"p":"El plazo para presentar la aclaración de un cargo no reconocido es de…","ops":["30 días hábiles","Seis meses","90 días naturales","10 días"],"correcta":2},{"p":"Si tu banco no resuelve tu aclaración, acudes a…","ops":["IMSS","CONDUSEF","PROFECO","SAT"],"correcta":1},{"p":"El REUS sirve para…","ops":["Que las instituciones financieras no te envíen publicidad","Cancelar tus tarjetas","Denunciar extorsiones","Consultar tu historial de crédito"],"correcta":0}],"c-ciberseguridad-m4":[{"p":"Acabas de dar tu clave dinámica a un falso asesor. Lo primero es…","ops":["Esperar el estado de cuenta","Cambiar tu foto de perfil","Desinstalar WhatsApp","Llamar al número oficial de tu banco para bloquear tarjetas y banca en línea"],"correcta":3},{"p":"Al cambiar contraseñas después de un fraude, conviene empezar por…","ops":["Tu cuenta de videojuegos","La contraseña del Wi-Fi","Tu correo electrónico","Tu cuenta de música"],"correcta":2},{"p":"Te robaron el WhatsApp. Además de recuperarlo, debes…","ops":["Publicar tu NIP para demostrar que eres tú","Avisar a tus contactos por otro medio que no depositen","Esperar a que el estafador lo devuelva","Comprar otro chip de inmediato sin avisar a nadie"],"correcta":1},{"p":"Una persona te ofrece recuperar tu dinero robado si le pagas por adelantado. Es…","ops":["Probablemente una segunda estafa","Un trámite oficial","Un servicio de CONDUSEF","Obligatorio"],"correcta":0},{"p":"El número para denunciar de forma anónima es…","ops":["911","088","800","089"],"correcta":3},{"p":"Ante una llamada de extorsión, lo recomendable es…","ops":["Dar más datos para que te crean","Depositar una parte","Colgar, localizar a tu familiar y no depositar","Negociar el monto"],"correcta":2},{"p":"La denuncia formal de un fraude se presenta ante…","ops":["Tu compañía de teléfono","La Fiscalía o el Ministerio Público","PROFECO","El SAT"],"correcta":1},{"p":"Una buena palabra clave familiar…","ops":["Solo la conoce la familia y no aparece en redes sociales","Es el nombre de la mascota","Se publica en el grupo de WhatsApp de la familia","Es la fecha de nacimiento del abuelo"],"correcta":0}]}});
